/// Establishment is allowed only on the current subnet of the explicitly
/// selected source. Android may change its routing table while a realm runs.
#[cfg(target_os = "android")]
pub(crate) fn android_on_link(source: IpAddr, target: IpAddr) -> bool {
    use std::net::Ipv4Addr;

    let (IpAddr::V4(source), IpAddr::V4(target)) = (source, target) else {
        return false;
    };
    if source.is_loopback() {
        return target.is_loopback();
    }
    if !source.is_private() || !target.is_private() {
        return false;
    }
    let Ok(interfaces) = network_interface::NetworkInterface::show() else {
        return false;
    };
    interfaces.into_iter().flat_map(|iface| iface.addr).any(|addr| {
        let network_interface::Addr::V4(address) = addr else {
            return false;
        };
        let Some(mask) = address.netmask else {
            return false;
        };
        if address.ip != source || mask == Ipv4Addr::UNSPECIFIED {
            return false;
        }
        let (source, target, mask) = (u32::from(source), u32::from(target), u32::from(mask));
        let host = target & !mask;
        (source & mask) == (target & mask) && (mask.count_zeros() <= 1 || (host != 0 && host != !mask))
    })
}

